import crypto from 'crypto'
import { db, sqliteDb } from '@/db/index.js'
import type Database from 'better-sqlite3'
import {
  quotes,
  quoteLineItems,
  vatRates,
  sequences,
} from '@/db/schema.js'
import { eq, sql, desc, asc } from 'drizzle-orm'

// ---------------------------------------------------------------------------
// Custom Error Classes
// ---------------------------------------------------------------------------

/** Thrown when a quote is not found. */
export class QuoteNotFoundError extends Error {
  constructor(public readonly id: string) {
    super(`Quote not found: ${id}`)
    this.name = 'QuoteNotFoundError'
  }
}

/** Thrown when an operation requires draft status but the quote is not in draft state. */
export class QuoteNotDraftError extends Error {
  constructor(public readonly id: string, public readonly currentStatus: string) {
    super(`Quote ${id} is not in draft state (current: ${currentStatus}). Only draft quotes can be modified.`)
    this.name = 'QuoteNotDraftError'
  }
}

/** Thrown when a quote line item is not found. */
export class QuoteLineItemNotFoundError extends Error {
  constructor(public readonly id: string) {
    super(`Quote line item not found: ${id}`)
    this.name = 'QuoteLineItemNotFoundError'
  }
}

// ---------------------------------------------------------------------------
// Types — request/response shapes
// ---------------------------------------------------------------------------

export type QuoteStatus = 'draft' | 'sent' | 'converted' | 'rejected'

export interface QuoteListResult {
  quotes: Array<{
    id: string
    quoteNumber: string
    customerId: string | null
    status: QuoteStatus
    notes: string | null
    createdAt: number
    updatedAt: number
  }>
  total: number
}

export interface QuoteDetail {
  id: string
  quoteNumber: string
  customerId: string | null
  status: QuoteStatus
  notes: string | null
  lineItems: QuoteLineItem[]
  createdAt: number
  updatedAt: number
}

export interface QuoteLineItem {
  id: string
  quoteId: string
  lineType: 'part' | 'labor' | 'bicycle'
  partId: string | null
  laborServiceId: string | null
  description: string
  quantity: number
  unitPriceNet: number
  vatRateId: string
  discountPercent: number | null
  lineTotalNet: number
  lineTotalVat: number
  lineTotalGross: number
  bicycleId: string | null
  bicycleBrand: string | null
  bicycleModel: string | null
  bicycleYear: number | null
  bicycleColor: string | null
  bicycleFrameSize: string | null
  createdAt: number
}

// ---------------------------------------------------------------------------
// Service Input Types — exported for use in route handlers (avoids `as any`)
// ---------------------------------------------------------------------------

/** Input shape for creating a quote line item via the service */
export interface CreateQuoteLineItemServiceInput {
  lineType: 'part' | 'labor' | 'bicycle'
  description: string
  quantity: number
  unitPriceNet: number
  vatRateId: string
  discountPercent?: number | null
  partId?: string | null
  laborServiceId?: string | null
  // Bicycle fields (only for lineType === 'bicycle')
  bicycleId?: string | null
  bicycleBrand?: string | null
  bicycleModel?: string | null
  bicycleYear?: number | null
  bicycleColor?: string | null
  bicycleFrameSize?: string | null
}

/** Input shape for updating a quote line item via the service */
export interface UpdateQuoteLineItemServiceInput {
  description?: string
  quantity?: number
  unitPriceNet?: number
  vatRateId?: string
  discountPercent?: number | null
  partId?: string | null
  laborServiceId?: string | null
  // Bicycle fields (only for lineType === 'bicycle')
  bicycleId?: string | null
  bicycleBrand?: string | null
  bicycleModel?: string | null
  bicycleYear?: number | null
  bicycleColor?: string | null
  bicycleFrameSize?: string | null
}



// ---------------------------------------------------------------------------
// Helper — Get VAT rate for a given vatRateId
// ---------------------------------------------------------------------------

async function getVatRate(vatRateId: string): Promise<{ rate: number }> {
  const [rate] = await db.select({ rate: vatRates.rate }).from(vatRates).where(eq(vatRates.id, vatRateId))
  if (!rate) {
    throw new Error(`VAT rate not found: ${vatRateId}`)
  }
  return rate
}

// ---------------------------------------------------------------------------
// Helper — Generate quote number from sequence
// ---------------------------------------------------------------------------

async function generateQuoteNumber(): Promise<string> {
  const updateResult = await db
    .update(sequences)
    .set({ currentValue: sql`${sequences.currentValue} + 1` })
    .where(eq(sequences.name, 'quote'))

  if (updateResult.changes === 0) {
    // Sequence doesn't exist yet — create it starting at 1
    await db.insert(sequences).values({ name: 'quote', currentValue: 1 })
  }

  const [seqRow] = await db
    .select({ currentValue: sequences.currentValue })
    .from(sequences)
    .where(eq(sequences.name, 'quote'))

  const seqNum = seqRow!.currentValue
  return `QT-${String(seqNum).padStart(4, '0')}`
}

// ---------------------------------------------------------------------------
// Helper — Enforce draft-only access on a quote
// ---------------------------------------------------------------------------

async function enforceDraftStatus(quoteId: string): Promise<void> {
  const [quote] = await db.select({ status: quotes.status }).from(quotes).where(eq(quotes.id, quoteId))

  if (!quote) {
    throw new QuoteNotFoundError(quoteId)
  }

  if (quote.status !== 'draft') {
    throw new QuoteNotDraftError(quoteId, quote.status as string)
  }
}

// ---------------------------------------------------------------------------
// Service Functions — Quote CRUD
// ---------------------------------------------------------------------------

/**
 * Create a new draft quote with auto-generated quote number.
 */
export async function createQuote(input: {
  customerId?: string | null
  notes?: string | null
}): Promise<QuoteDetail> {
  const quoteNumber = await generateQuoteNumber()
  const now = Date.now()

  const [inserted] = await db
    .insert(quotes)
    .values({
      id: crypto.randomUUID(),
      quoteNumber,
      customerId: input.customerId ?? null,
      status: 'draft',
      notes: input.notes ?? null,
      createdAt: now,
      updatedAt: now,
    })
    .returning()

  return getQuoteDetail(inserted.id)
}

/**
 * List quotes with optional status filter. Returns newest first.
 */
export async function getQuotesList(statusFilter?: string): Promise<QuoteListResult> {
  const typedStatus = statusFilter as 'draft' | 'sent' | 'converted' | 'rejected'
  const whereClause = statusFilter ? eq(quotes.status, typedStatus) : undefined

  const quoteRows = await db
    .select({
      id: quotes.id,
      quoteNumber: quotes.quoteNumber,
      customerId: quotes.customerId,
      status: quotes.status,
      notes: quotes.notes,
      createdAt: quotes.createdAt,
      updatedAt: quotes.updatedAt,
    })
    .from(quotes)
    .where(whereClause)
    .orderBy(desc(quotes.createdAt))

  const total = quoteRows.length

  return {
    quotes: quoteRows,
    total,
  }
}

/**
 * Get a single quote by ID with its line items.
 */
export async function getQuoteById(quoteId: string): Promise<QuoteDetail> {
  const [quote] = await db.select().from(quotes).where(eq(quotes.id, quoteId))

  if (!quote) {
    throw new QuoteNotFoundError(quoteId)
  }

  return getQuoteDetail(quoteId)
}

/**
 * Update draft-only fields on a quote (customerId, notes).
 */
export async function updateQuote(quoteId: string, input: {
  customerId?: string | null
  notes?: string | null
}): Promise<QuoteDetail> {
  // Enforce draft status before allowing updates
  await enforceDraftStatus(quoteId)

  const now = Date.now()
  await db
    .update(quotes)
    .set({
      ...(input.customerId !== undefined && { customerId: input.customerId }),
      ...(input.notes !== undefined && { notes: input.notes }),
      updatedAt: now,
    })
    .where(eq(quotes.id, quoteId))

  return getQuoteDetail(quoteId)
}

/**
 * Delete a draft quote and all its line items.
 */
export async function deleteQuote(quoteId: string): Promise<void> {
  // Enforce draft status before allowing deletion
  await enforceDraftStatus(quoteId)

  // Delete line items first (foreign key constraint)
  await db.delete(quoteLineItems).where(eq(quoteLineItems.quoteId, quoteId))

  // Delete the quote
  await db.delete(quotes).where(eq(quotes.id, quoteId))
}

// ---------------------------------------------------------------------------
// Service Functions — Quote Line Item CRUD
// ---------------------------------------------------------------------------

/**
 * Create a new line item for a quote. Validates draft status and calculates totals.
 */
export async function createQuoteLineItem(quoteId: string, input: CreateQuoteLineItemServiceInput): Promise<QuoteLineItem> {
  // Enforce draft status on parent quote
  await enforceDraftStatus(quoteId)

  const now = Date.now()

  // Fetch VAT rate to calculate tax amounts
  const vatRate = await getVatRate(input.vatRateId)

  // Calculate line totals (discount in basis points: 100 = 1%, 10000 = 100%)
  const discountMultiplier = input.discountPercent != null ? 1 - input.discountPercent / 10000 : 1
  const lineTotalNet = Math.round(input.unitPriceNet * input.quantity * discountMultiplier)
  const lineTotalVat = Math.round(lineTotalNet * vatRate.rate / 10000)
  const lineTotalGross = lineTotalNet + lineTotalVat

  const lineItemId = crypto.randomUUID()

  // Use raw SQL for insert to avoid Drizzle ORM issues with spread columns
  const client = sqliteDb as Database.Database

  client.prepare(
    'INSERT INTO quote_line_items (id, quote_id, line_type, part_id, labor_service_id, description, quantity, unit_price_net, vat_rate_id, discount_percent, line_total_net, line_total_vat, line_total_gross, bicycle_id, bicycle_brand, bicycle_model, bicycle_year, bicycle_color, bicycle_frame_size, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)'
  ).run(
    lineItemId,
    quoteId,
    input.lineType,
    input.partId ?? null,
    input.laborServiceId ?? null,
    input.description,
    input.quantity,
    input.unitPriceNet,
    input.vatRateId,
    input.discountPercent !== undefined ? input.discountPercent : null,
    lineTotalNet,
    lineTotalVat,
    lineTotalGross,
    input.bicycleId ?? null,
    input.bicycleBrand ?? null,
    input.bicycleModel ?? null,
    input.bicycleYear ?? null,
    input.bicycleColor ?? null,
    input.bicycleFrameSize ?? null,
    now
  )

  const [inserted] = await db.select().from(quoteLineItems).where(eq(quoteLineItems.id, lineItemId))

  return inserted as unknown as QuoteLineItem
}

/**
 * Update an existing line item. Validates draft status on parent quote.
 */
export async function updateQuoteLineItem(quoteId: string, lineItemId: string, input: UpdateQuoteLineItemServiceInput): Promise<QuoteLineItem> {
  // Enforce draft status on parent quote
  await enforceDraftStatus(quoteId)

  // Fetch existing line item to get its type and current values for recalculation
  const [existing] = await db.select().from(quoteLineItems).where(eq(quoteLineItems.id, lineItemId))

  if (!existing) {
    throw new QuoteLineItemNotFoundError(lineItemId)
  }

  // Verify the line item belongs to this quote
  if (existing.quoteId !== quoteId) {
    throw new QuoteLineItemNotFoundError(lineItemId)
  }

  // Determine effective values for recalculation (used when fields aren't being updated)
  const effUnitPriceNet = input.unitPriceNet ?? existing.unitPriceNet
  const effQuantity = input.quantity ?? existing.quantity
  const effDiscountPercent = input.discountPercent !== undefined ? (input.discountPercent != null ? input.discountPercent : null) : existing.discountPercent
  const effVatRateId = input.vatRateId ?? existing.vatRateId

  // Fetch VAT rate for recalculation
  const vatRate = await getVatRate(effVatRateId)

  // Recalculate totals based on effective values
  const discountMultiplier = effDiscountPercent != null ? 1 - effDiscountPercent / 10000 : 1
  const lineTotalNet = Math.round(effUnitPriceNet * effQuantity * discountMultiplier)
  const lineTotalVat = Math.round(lineTotalNet * vatRate.rate / 10000)
  const lineTotalGross = lineTotalNet + lineTotalVat

  // Build dynamic SQL with only the fields that were provided
  const setClauses: string[] = []
  const params: unknown[] = []

  if (input.description !== undefined) {
    setClauses.push('description = ?')
    params.push(input.description)
  }
  if (input.quantity !== undefined) {
    setClauses.push('quantity = ?')
    params.push(input.quantity)
  }
  if (input.unitPriceNet !== undefined) {
    setClauses.push('unit_price_net = ?')
    params.push(input.unitPriceNet)
  }
  if (input.vatRateId !== undefined) {
    setClauses.push('vat_rate_id = ?')
    params.push(input.vatRateId)
  }
  if (input.discountPercent !== undefined) {
    setClauses.push('discount_percent = ?')
    params.push(input.discountPercent != null ? input.discountPercent : null)
  }

  // Always update totals (no updated_at column on quote_line_items)
  setClauses.push('line_total_net = ?', 'line_total_vat = ?', 'line_total_gross = ?')
  params.push(lineTotalNet, lineTotalVat, lineTotalGross)

  // Type-specific fields (always update if provided)
  if (input.partId !== undefined) {
    setClauses.push('part_id = ?')
    params.push(input.partId ?? null)
  }
  if (input.laborServiceId !== undefined) {
    setClauses.push('labor_service_id = ?')
    params.push(input.laborServiceId ?? null)
  }
  if (input.bicycleId !== undefined) {
    setClauses.push('bicycle_id = ?')
    params.push(input.bicycleId ?? null)
  }
  if (input.bicycleBrand !== undefined) {
    setClauses.push('bicycle_brand = ?')
    params.push(input.bicycleBrand ?? null)
  }
  if (input.bicycleModel !== undefined) {
    setClauses.push('bicycle_model = ?')
    params.push(input.bicycleModel ?? null)
  }
  if (input.bicycleYear !== undefined) {
    setClauses.push('bicycle_year = ?')
    params.push(input.bicycleYear ?? null)
  }
  if (input.bicycleColor !== undefined) {
    setClauses.push('bicycle_color = ?')
    params.push(input.bicycleColor ?? null)
  }
  if (input.bicycleFrameSize !== undefined) {
    setClauses.push('bicycle_frame_size = ?')
    params.push(input.bicycleFrameSize ?? null)
  }

  // Use raw SQL for update to avoid Drizzle ORM issues with spread columns
  const client = sqliteDb as Database.Database

  if (setClauses.length === 0) {
    // No fields to update — just return the existing item
    const [existingItem] = await db.select().from(quoteLineItems).where(eq(quoteLineItems.id, lineItemId))
    return existingItem as unknown as QuoteLineItem
  }

  client.prepare(
    `UPDATE quote_line_items SET ${setClauses.join(', ')} WHERE id = ?`
  ).run(...params, lineItemId)

  const [updated] = await db.select().from(quoteLineItems).where(eq(quoteLineItems.id, lineItemId))

  return updated as unknown as QuoteLineItem
}

/**
 * Delete a line item. Validates draft status on parent quote.
 */
export async function deleteQuoteLineItem(quoteId: string, lineItemId: string): Promise<void> {
  // Enforce draft status on parent quote
  await enforceDraftStatus(quoteId)

  const [existing] = await db.select().from(quoteLineItems).where(eq(quoteLineItems.id, lineItemId))

  if (!existing) {
    throw new QuoteLineItemNotFoundError(lineItemId)
  }

  // Verify the line item belongs to this quote
  if (existing.quoteId !== quoteId) {
    throw new QuoteLineItemNotFoundError(lineItemId)
  }

  await db.delete(quoteLineItems).where(eq(quoteLineItems.id, lineItemId))
}

// ---------------------------------------------------------------------------
// Helper — Build full quote detail with line items
// ---------------------------------------------------------------------------

async function getQuoteDetail(quoteId: string): Promise<QuoteDetail> {
  const [quote] = await db.select().from(quotes).where(eq(quotes.id, quoteId))

  if (!quote) {
    throw new QuoteNotFoundError(quoteId)
  }

  const lineItemsRows = await db
    .select()
    .from(quoteLineItems)
    .where(eq(quoteLineItems.quoteId, quoteId))
    .orderBy(asc(quoteLineItems.id))

  return {
    id: quote.id,
    quoteNumber: quote.quoteNumber,
    customerId: quote.customerId,
    status: quote.status as QuoteStatus,
    notes: quote.notes,
    lineItems: lineItemsRows as unknown as QuoteLineItem[],
    createdAt: quote.createdAt,
    updatedAt: quote.updatedAt,
  }
}

import crypto from 'crypto'
import { db, sqliteDb } from '@/db/index.js'
import type Database from 'better-sqlite3'
import { sales, saleLineItems, payments, vatRates, paymentAllocations, stockMovements, sequences } from '@/db/schema.js'
import { desc, eq, inArray, sql, sum, asc } from 'drizzle-orm'
import { createDirectSaleInputSchema } from '@pi-skeleton/shared/validations/sales'
import { computeLineTotals } from '@shared/lib/pricing.js'

// ============================================================================
// Types
// ============================================================================

/** Input for creating a direct sale (validated via Zod schema) */
export interface CreateDirectSaleInput {
  /** Optional customer ID — null/absent means walk-in */
  customerId?: string | null
  /** Payment method */
  paymentMethod: 'cash' | 'card'
  /** Line items being purchased */
  lineItems: Array<{
    partId: string
    quantity: number
    unitPriceNet: number
    vatRateId: string
    description: string
    discountPercent?: number | null
  }>
}

/** Result returned after a successful sale creation */
export interface SaleResult {
  /** The created sale header */
  sale: typeof sales.$inferSelect
  /** The created payment record */
  payment: typeof payments.$inferSelect
  /** All line items for this sale */
  lineItems: typeof saleLineItems.$inferSelect[]
}

/** Error thrown when stock validation fails */
export class InsufficientStockError extends Error {
  constructor(public readonly shortfalls: Array<{ partId: string; requested: number; available: number }>) {
    super(`Insufficient stock for ${shortfalls.length} part(s)`)
    this.name = 'InsufficientStockError'
  }
}

/** Error thrown when a sale is not found */
export class SaleNotFoundError extends Error {
  constructor(public readonly id: string) {
    super(`Sale not found: ${id}`)
    this.name = 'SaleNotFoundError'
  }
}

// ============================================================================
// Stock validation — aggregates from stock_movements (no denormalized trust)
// ============================================================================

/** Input: one part with a requested quantity to validate. */
interface StockCheckRequest {
  /** Part ID to check availability for */
  partId: string
  /** Number of units the caller wants to sell */
  requestedQuantity: number
}

/** One part that does not have enough stock. */
interface ShortfallDetail {
  /** The part ID with insufficient stock */
  partId: string
  /** How many units were requested */
  requested: number
  /** How many units are actually available (computed from movements) */
  available: number
}

/** Result of validating a batch of stock requests. */
interface StockValidationResult {
  /** true if every part has sufficient stock; false otherwise */
  valid: boolean
  /** Non-empty only when valid is false — lists each short-falling part */
  shortfalls: ShortfallDetail[]
}

/**
 * Validate whether requested quantities are available in stock.
 *
 * Computes available stock per part by summing `quantityDelta` from the
 * `stock_movements` table — never trusts denormalized `quantityOnHand`.
 */
async function validateStockAvailability(
  requests: StockCheckRequest[]
): Promise<StockValidationResult> {
  if (requests.length === 0) {
    return { valid: true, shortfalls: [] }
  }

  const partIds = [...new Set(requests.map(r => r.partId))]

  const aggregationQuery = db
    .select({
      partId: stockMovements.partId,
      totalDelta: sql<number>`COALESCE(${sum(stockMovements.quantityDelta)}, 0)`
    })
    .from(stockMovements)
    .where(inArray(stockMovements.partId, partIds))
    .groupBy(stockMovements.partId)

  const aggregationResults = await aggregationQuery

  const availableMap = new Map<string, number>()
  for (const row of aggregationResults) {
    availableMap.set(row.partId, Number(row.totalDelta))
  }

  const shortfalls: ShortfallDetail[] = []
  for (const req of requests) {
    const available = availableMap.get(req.partId) ?? 0
    if (req.requestedQuantity > available) {
      shortfalls.push({
        partId: req.partId,
        requested: req.requestedQuantity,
        available
      })
    }
  }

  shortfalls.sort((a, b) => a.partId.localeCompare(b.partId))

  return {
    valid: shortfalls.length === 0,
    shortfalls
  }
}

// ============================================================================
// Sequence helper — atomic increment for document numbering
// ============================================================================

/**
 * Get the next sequential value for a document number sequence.
 * Atomically increments the counter and returns the new value.
 */
async function getNextValue(name: string): Promise<number> {
  const updateResult = await db
    .update(sequences)
    .set({ currentValue: sql`${sequences.currentValue} + 1` })
    .where(eq(sequences.name, name))

  if (updateResult.changes === 0) {
    await db.insert(sequences).values({ name, currentValue: 1 })
    return 1
  }

  const [row] = await db
    .select({ currentValue: sequences.currentValue })
    .from(sequences)
    .where(eq(sequences.name, name))

  return row!.currentValue
}

// ============================================================================
// Public API
// ============================================================================

/**
 * Create a direct sale atomically in a single database transaction.
 *
 * Flow: validate input → check stock → get sequence number → insert sale header
 *       → insert line items → insert payment → insert allocation → insert stock movements
 * All-or-nothing: any failure rolls back everything.
 *
 * @param rawInput — Unvalidated input object (will be validated via Zod)
 * @returns Sale result with created entities
 */
export async function createDirectSale(rawInput: unknown): Promise<SaleResult> {
  // Validate input via Zod schema
  const parsed = createDirectSaleInputSchema.safeParse(rawInput)
  if (!parsed.success) {
    throw new Error(`Invalid sale input: ${parsed.error.message}`)
  }

  const input = parsed.data as CreateDirectSaleInput

  // ---------------------------------------------------------------------------
  // Step 1: Validate stock availability for all line items
  // ---------------------------------------------------------------------------
  const stockRequests = input.lineItems.map((item) => ({
    partId: item.partId,
    requestedQuantity: item.quantity
  }))

  const stockResult = await validateStockAvailability(stockRequests)
  if (!stockResult.valid) {
    throw new InsufficientStockError(stockResult.shortfalls)
  }

  // ---------------------------------------------------------------------------
  // Step 2: Get sale number from sequence table (atomic increment)
  // ---------------------------------------------------------------------------
  const saleNumberSeq = await getNextValue('sale')
  const saleNumber = `SA-${String(saleNumberSeq).padStart(4, '0')}`

  // ---------------------------------------------------------------------------
  // Step 3: Fetch VAT rates needed for line item calculations
  // ---------------------------------------------------------------------------
  const allVatRates = await db.select({ id: vatRates.id, rate: vatRates.rate }).from(vatRates)
  const vatRatesMap = new Map<string, number>()
  for (const row of allVatRates) {
    vatRatesMap.set(row.id, Number(row.rate))
  }

  // ---------------------------------------------------------------------------
  // Step 4: Compute line item totals using shared pricing lib
  // ---------------------------------------------------------------------------
  const lineItemsData = input.lineItems.map((item) => {
    const vatRateBps = vatRatesMap.get(item.vatRateId) ?? 0
    const totals = computeLineTotals(item.unitPriceNet, item.quantity, item.discountPercent, vatRateBps)

    return {
      partId: item.partId,
      quantity: item.quantity,
      unitPriceNet: item.unitPriceNet,
      vatRateId: item.vatRateId,
      description: item.description,
      discountPercent: item.discountPercent ?? null,
      lineTotalNet: totals.net,
      lineTotalVat: totals.vat,
      lineTotalGross: totals.gross,
      lineType: 'part' as const
    }
  })

  const subtotalNet = lineItemsData.reduce((sum, item) => sum + item.lineTotalNet, 0)
  const vatTotal = lineItemsData.reduce((sum, item) => sum + item.lineTotalVat, 0)
  const totalGross = subtotalNet + vatTotal

  // ---------------------------------------------------------------------------
  // Step 5: Execute single transaction — all inserts or nothing
  // ---------------------------------------------------------------------------
  const saleId = crypto.randomUUID()
  const paymentId = crypto.randomUUID()

  const client = sqliteDb as Database.Database
  const run = (sqlStr: string, params?: unknown[]) => {
    return client.prepare(sqlStr).run(...(params ?? []))
  }

  try {
    // Begin transaction
    run('BEGIN TRANSACTION')

    // Insert sale header
    run(
      'INSERT INTO sales (id, sale_number, customer_id, source_type, source_id, status, subtotal_net, vat_total, total_gross, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
      [saleId, saleNumber, input.customerId ?? null, 'direct_sale', null, 'completed', subtotalNet, vatTotal, totalGross, Date.now()]
    )

    const now = Date.now()

    // Insert line items
    for (const item of lineItemsData) {
      const lineItemId = crypto.randomUUID()
      run(
        'INSERT INTO sale_line_items (id, sale_id, line_type, part_id, description, quantity, unit_price_net, vat_rate_id, discount_percent, line_total_net, line_total_vat, line_total_gross, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
        [lineItemId, saleId, item.lineType, item.partId, item.description, item.quantity, item.unitPriceNet, item.vatRateId, item.discountPercent, item.lineTotalNet, item.lineTotalVat, item.lineTotalGross, now]
      )
    }

    // Insert payment record
    run(
      'INSERT INTO payments (id, method, amount, created_at) VALUES (?, ?, ?, ?)',
      [paymentId, input.paymentMethod, totalGross, now]
    )

    // Insert payment allocation (payment → sale)
    run(
      'INSERT INTO payment_allocations (id, payment_id, target_type, target_id, allocated_amount) VALUES (?, ?, ?, ?, ?)',
      [crypto.randomUUID(), paymentId, 'sale', saleId, totalGross]
    )

    // Insert stock movements (negative deltas for each part sold)
    for (const item of input.lineItems) {
      run(
